/**
 * Audience Programs — Expansion pack (12 additional 7-day programs).
 * Same shape as the four flagships in audiencePrograms.ts.
 * Each program: 1 guru, 7 days, teaching + practice + reflection per day.
 */
import type { ShowroomProgram } from "../showroomPrograms";

// ============================================================================
// 1. CREATORS — THE CREATOR'S BLOCK (Saraswati)
// ============================================================================
const CREATOR_BLOCK: ShowroomProgram = {
  slug: "creator-flow-and-block",
  title: "The Creator's Block",
  subtitle: "Seven days for writers, designers, musicians — moving from stuck to flow without forcing it.",
  guru: "Saraswati",
  guruRole: "the goddess of speech, learning, and the arts — patron of every human who has ever stared at a blank page",
  theme: "🎨",
  color: "from-teal-500/30 via-cyan-500/20 to-sky-500/10",
  category: "art",
  audience: "creators",
  duration: "7 days",
  promise: "By day 7 you'll have a daily start ritual, a diagnosis of your specific block, and one finished small thing — not a masterpiece, a finish.",
  days: [
    { day: 1, title: "The Block Has A Name",
      oneLine: "'Creator's block' is four different problems. Fixing the wrong one wastes months.",
      reading: `There is no such thing as generic block. What we call block is one of four: fear (of judgment), fatigue (empty tank), fog (unclear intent), or friction (bad tools, bad room, bad time). Each has a different fix and they do not substitute for each other. Rest will not solve fear. Courage will not solve fatigue.\n\nSaraswati is often shown with a book, a vina, a mala, and a swan. Four objects, four modes. She does not treat creativity as one thing.\n\nThis week begins by naming which of the four is actually holding you. Get that wrong and every practice below will feel useless.`,
      practice: { name: "Name The Block", durationMin: 6,
        instructions: `1. Write the project you're stuck on at the top of a page.\n2. Ask each: "Am I afraid of how this will land?" / "Am I actually rested?" / "Do I know what this is trying to be?" / "Is my workspace/schedule/tool actively fighting me?"\n3. Score each 0–10.\n4. The highest score is your real block for this week. Circle it.` },
      reflection: "Which of the four have you been misdiagnosing all year?" },
    { day: 2, title: "The Start Ritual",
      oneLine: "Professionals don't wait for inspiration. They have a doorway that opens the room.",
      reading: `Every working artist has a short, boring ritual that gets them into the chair. Not a mood. A trigger. Coffee at the same cup, same playlist, same first line ("okay, let's see"), same warm-up sketch. The ritual is not magic; it's a Pavlovian on-ramp that removes the daily negotiation.\n\nAmateurs try to feel inspired first. Professionals sit down first and let inspiration catch up.\n\nToday you design yours.`,
      practice: { name: "Design Your On-Ramp", durationMin: 8,
        instructions: `1. Pick 3 sensory anchors: one sound (playlist/silence), one object (cup/pen/lamp), one physical action (30 pushups / stretch / walk to desk).\n2. Sequence them in order.\n3. Commit: for the next 6 days you do these three, in order, before you start.\n4. Do them now, then work for 20 minutes.` },
      reflection: "What have you been using instead of a ritual — willpower, guilt, deadline panic?" },
    { day: 3, title: "Bad First Drafts On Purpose",
      oneLine: "The block is usually your inner editor showing up before your inner writer has stood up.",
      reading: `Two people live in every creator: the maker and the judge. In flow they take turns. In block, the judge speaks first, every time, and the maker never gets started.\n\nThe fix is not to kill the judge — you need them for revision. The fix is to give the maker a protected sandbox where the judge is not allowed. Anne Lamott called them "shitty first drafts." Hemingway called it "writing drunk, editing sober." Saraswati calls it *vagvidya* — the free flow of speech before it is refined.`,
      practice: { name: "The Ugly Twenty", durationMin: 20,
        instructions: `1. Set a timer, 20 minutes.\n2. Work on the project. The only rule: it must be bad on purpose. Aim for embarrassing.\n3. No deleting. No editing. If you hate it, keep going.\n4. When the timer ends, stop. Do not read it back today.` },
      reflection: "What would you make if 'good' was not allowed for the first hour?" },
    { day: 4, title: "Steal Like An Ancestor",
      oneLine: "Originality is a myth. Lineage is a practice.",
      reading: `Every artist you love is a remix of the ones they loved. The romantic idea of the lone original genius is a 200-year-old marketing story. Before that, artists apprenticed, copied masters, and *earned* their voice through years of imitation.\n\nSaraswati sits on a swan because she is the tradition of learning itself. To be in her lineage is to admit you were made by others and to honor that debt openly.\n\nBlock often lifts the moment you stop trying to be new and start trying to *continue* someone.`,
      practice: { name: "Three Ancestors", durationMin: 15,
        instructions: `1. Pick 3 artists (dead or alive, any medium) whose work you love.\n2. For each, write one sentence: "What they taught me is __."\n3. For your current project: pick ONE of them and ask, "If I were making this as their student, what would change?"\n4. Do 15 minutes of work in that mode.` },
      reflection: "Whose apprentice are you, actually?" },
    { day: 5, title: "The Empty Tank",
      oneLine: "Input famine looks like output block. You cannot pour from a dry well.",
      reading: `Most 'block' after a productive stretch is simply that you've spent months outputting and weeks not inputting. The maker is not broken; the shelves are empty.\n\nInput is not scrolling. Scrolling is empty calories. Real input is: long reading, live music, museums, walking in nature, sitting with older artists, silence.\n\nToday is deliberate refill.`,
      practice: { name: "Fill The Well", durationMin: 45,
        instructions: `1. No phone.\n2. Pick one: read 30 pages of a real book / listen to a full album with eyes closed / walk 45 minutes in a place with trees / visit a gallery.\n3. Take a small notebook. Write down 3 things that struck you.\n4. Do not try to 'apply' them today. Just refill.` },
      reflection: "When did you last put something into yourself that was not for immediate output?" },
    { day: 6, title: "The Room You Work In",
      oneLine: "You become the room. Bad rooms make bad art.",
      reading: `Rooms train nervous systems. A cluttered, over-lit, notification-heavy room trains a scattered mind. A specific, quiet, dedicated room trains a focused one. This is not woo — it is classical conditioning.\n\nYou don't need a studio. You need one square meter that means only one thing: *this is where I make*. Nothing else happens there. No email, no lunch, no argument.`,
      practice: { name: "One Square Meter", durationMin: 20,
        instructions: `1. Choose one physical spot (desk corner, kitchen table half, floor cushion).\n2. Remove everything from it that is not for making.\n3. Add one object that says "make" (a specific pen, a candle, a headphone).\n4. From now on, only work happens here. Nothing else. Ever.\n5. Sit there. Work 20 minutes.` },
      reflection: "Where in your home have you accidentally trained yourself into distraction?" },
    { day: 7, title: "Finish One Small Thing",
      oneLine: "Finishing changes the nervous system. Starting doesn't.",
      reading: `The most important muscle a creator builds is the finish. Not the big finish — the small, weekly, ordinary finish. Finishing tells the brain: things you start end. It reduces the terror of starting new things.\n\nMost blocked creators have twelve half-things. What breaks the block is not a thirteenth start. It is one honest finish, however small.`,
      practice: { name: "Ship Something Tiny", durationMin: 60,
        instructions: `1. Pick the smallest possible unit of your project (one paragraph, one sketch, one 30-second demo).\n2. Finish it to the point where you could show it to one person.\n3. Actually show it to one person today.\n4. Do not apologize for its size.` },
      reflection: "What have you not finished this year because you were waiting to make it 'good'?" },
  ],
};

// ============================================================================
// 2. PARENTS — THE PATIENT PARENT (Yashoda)
// ============================================================================
const PATIENT_PARENT: ShowroomProgram = {
  slug: "parent-patience-presence",
  title: "The Patient Parent",
  subtitle: "Seven days of nervous-system tools for the hardest job on earth — being present with a small human when you are exhausted.",
  guru: "Yashoda",
  guruRole: "Krishna's foster mother — the archetype of the parent who raised god itself while running a household",
  theme: "🕊️",
  color: "from-emerald-500/30 via-green-500/20 to-lime-500/10",
  category: "love",
  audience: "parents",
  duration: "7 days",
  promise: "By day 7 you'll have a repair protocol for after you snap, a five-minute reset that fits between diapers, and one honest agreement with yourself about what 'good enough parent' actually means.",
  days: [
    { day: 1, title: "The Baseline You're Working From",
      oneLine: "You are not a bad parent. You are an undersept, understimulated, over-touched nervous system trying to be a good parent.",
      reading: `Before any parenting technique matters, one number matters: how depleted is the adult in the room. A parent running on 5 hours of interrupted sleep, no solo time, and constant sensory input is not a personality — they are a physiological emergency.\n\nYashoda's stories are full of her losing her temper with the child-god Krishna. Even the mother of god snapped. What made her a great mother was not that she never lost it — it was what she did next.\n\nThis week starts with the honest baseline, not the ideal.`,
      practice: { name: "The Baseline Card", durationMin: 5,
        instructions: `1. Write your honest numbers: last night's sleep hours, minutes alone today, last time you ate without a child on you.\n2. Under it write: "Given this, I did __ well today."\n3. Keep the card. Look at it the next time you feel like a bad parent.` },
      reflection: "How would you talk to a friend running on your current sleep debt?" },
    { day: 2, title: "The 5-Minute Reset",
      oneLine: "You cannot leave. You can still reset. The bathroom counts.",
      reading: `Traditional advice says take a walk, take a bath. Parents of small children cannot. What they can do is a 5-minute reset in a bathroom, a parked car, or a locked pantry. The point is not luxury. The point is one deliberate exhale before the next demand.\n\nThe body doesn't need a spa. It needs the parasympathetic nervous system to be told, once an hour, "we are not being chased."`,
      practice: { name: "The Bathroom Reset", durationMin: 5,
        instructions: `1. Next time you can lock a door for 5 minutes, do.\n2. Sit. Cold water on wrists.\n3. 6 slow breaths, exhale twice as long as inhale.\n4. One sentence out loud: "I am the adult and I am okay."\n5. Return.` },
      reflection: "When did you last take five deliberate minutes without a child today?" },
    { day: 3, title: "The Rupture And Repair",
      oneLine: "Children are not damaged by parents who snap. They are damaged by parents who never come back and make it right.",
      reading: `Every parent snaps. The research is clear: what predicts a child's secure attachment is not the absence of rupture but the presence of *repair*. A parent who yells and then, ten minutes later, kneels down and says "I lost my temper, that wasn't your fault, I'm sorry" is doing the actual work of raising a stable adult.\n\nRepair teaches the child: relationships bend and mend. That single skill is what most adults are still trying to learn in therapy.`,
      practice: { name: "The Repair Script", durationMin: 3,
        instructions: `1. Memorize: "I got upset. That was mine, not yours. I love you. Let's start again."\n2. Next time you snap — even mildly — kneel to their eye level within 15 minutes and say it.\n3. Do not over-explain. Do not add "but you were __."` },
      reflection: "Who never repaired with you as a child? What would it have meant if they had?" },
    { day: 4, title: "Presence Is Not Attention All Day",
      oneLine: "Ten minutes of undivided attention beats ten hours of half-present hovering.",
      reading: `Modern parents are with their children constantly and *present* with them rarely. The child feels both — the constant proximity and the emotional absence — and the confusion is worse than a working parent who arrives fully.\n\nThe fix is dosed presence. Short, undivided, phone-away, floor-level attention. Ten minutes a day of this beats eight hours of "I'm right here honey" while scrolling.`,
      practice: { name: "The Ten Minute Floor", durationMin: 10,
        instructions: `1. Phone in another room.\n2. Get on the floor at their level.\n3. Let them lead. You follow. No teaching, no correcting, no photographing.\n4. Ten minutes. Then say, "That was our special time," and get up.` },
      reflection: "How would your child describe your face when they talk to you?" },
    { day: 5, title: "The Enemy Called Comparison",
      oneLine: "You are not parenting your child. You are parenting an imaginary child on Instagram and losing.",
      reading: `Social media has done to parenting what airbrushed magazines did to bodies. Every parent is now competing against a highlight reel of thousands of other parents' best moments, stitched together into a fantasy no real family lives.\n\nYashoda had no Instagram. She had a village, a few peers, and her own child. That was the whole comparison set. It made her sane.`,
      practice: { name: "The Feed Fast", durationMin: 10,
        instructions: `1. Unfollow every parenting influencer today. Every one.\n2. Follow instead: one honest friend who has kids, one grandparent, no one else.\n3. For 7 days, when the urge to compare comes, look at your actual child instead of a phone.` },
      reflection: "Which imaginary parent have you been trying to be?" },
    { day: 6, title: "The Marriage Under The Parenting",
      oneLine: "The best gift you give your child is two adults who still like each other.",
      reading: `The relationship between the parents is the emotional weather the child grows up inside. When it is stormy and unaddressed, the child learns storms are normal. When it is warm, the child grows up expecting warmth from partners.\n\nMost couples with young children stop being partners and become co-managers. The kids feel it. Ten minutes of adult connection per day, protected, is a parenting act — not a self-indulgent one.`,
      practice: { name: "The Ten Minute Check-In", durationMin: 10,
        instructions: `1. With your co-parent, after kids are down: sit, no phones, no logistics.\n2. Each answers: "What was hard today? What was good? What do I need tomorrow?"\n3. Listen. Do not fix.\n4. End with one physical touch.\n(If single parent: do this with your closest adult ally.)` },
      reflection: "When did you last look your co-parent in the eye without discussing the child?" },
    { day: 7, title: "The Good Enough Parent",
      oneLine: "Winnicott's phrase, not a consolation prize: the good enough parent is what makes the securely attached adult.",
      reading: `The psychoanalyst Donald Winnicott found something unexpected: children of "perfect" parents were often more anxious than children of "good enough" ones. The perfect parent creates a child who expects the world to be perfectly attuned to them — and the world isn't.\n\nThe good enough parent shows up most of the time, repairs when they fail, holds the child through their frustrations, and does not perform.\n\nBy that standard, you may already be doing the work. You have not been told this enough.`,
      practice: { name: "The Good Enough Vow", durationMin: 10,
        instructions: `1. Write: "I am a good enough parent when I __." Fill three specifics.\n2. Write: "I am not required to __." List three fantasies you're releasing (be Pinterest, be always calm, be their entire social world).\n3. Read it aloud.\n4. Keep it somewhere you'll see next month.` },
      reflection: "What would change if you believed you were already enough?" },
  ],
};

// ============================================================================
// 3. STUDENTS — FOCUS UNDER PRESSURE (Ganesha)
// ============================================================================
const STUDENT_FOCUS: ShowroomProgram = {
  slug: "student-focus-under-pressure",
  title: "Focus Under Pressure",
  subtitle: "Seven days for students — attention training that survives phones, exams, and social noise.",
  guru: "Ganesha",
  guruRole: "the remover of obstacles, patron of scholars and the writing of the Mahabharata itself",
  theme: "📚",
  color: "from-yellow-500/30 via-amber-500/20 to-orange-500/10",
  category: "attention",
  audience: "students",
  duration: "7 days",
  promise: "By day 7 you'll have a study block that actually works, a phone protocol that removes the constant pull, and one exam-day breath you can trust.",
  days: [
    { day: 1, title: "Attention Is A Muscle",
      oneLine: "You do not have a focus problem. You have an untrained attention muscle in a world designed to atrophy it.",
      reading: `Attention is not a personality trait. It is a physiological capacity that grows and shrinks based on what you do with it. Every hour of scrolling shortens it. Every hour of sustained reading lengthens it.\n\nMost students think they were "born distractable." The average teenager in 2005 was not distractable. The environment changed. The organism responded.\n\nThe good news: it retrains fast. Two weeks of deliberate practice measurably increases sustained attention span. This week is the start.`,
      practice: { name: "The Baseline Timer", durationMin: 25,
        instructions: `1. Pick one textbook or one problem set.\n2. Phone in another room, not just face down.\n3. Timer: 25 minutes. Only that one thing.\n4. Note how many times your mind pulled to something else. That's your baseline number.\n5. Do not judge it. Just record it.` },
      reflection: "What number would surprise your parents about your average continuous focus time?" },
    { day: 2, title: "The Phone Is Not Neutral",
      oneLine: "Every phone in the room, even face down, drops working memory measurably. This is data, not opinion.",
      reading: `Ward et al., University of Texas 2017: participants performed cognitive tasks with their phone in three conditions — on the desk, in the pocket, in another room. Performance dropped linearly the closer the phone was. Even when it was off.\n\nThe brain spends silent bandwidth ignoring it. That bandwidth is what you were trying to study with.\n\nThe fix is not "willpower." The fix is distance.`,
      practice: { name: "Another Room Protocol", durationMin: 5,
        instructions: `1. Designate one spot in your home that is "phone jail" (a drawer, a shelf).\n2. Before every study block, phone goes there.\n3. Set an audible timer on it if you're waiting on a call.\n4. Study block ends → then you retrieve it.\n5. Do this for all 6 remaining days.` },
      reflection: "How often do you check your phone in a normal hour? Guess, then count for an hour and compare." },
    { day: 3, title: "Deep vs Shallow Study",
      oneLine: "Rereading is not studying. It's the feeling of studying. Retrieval is studying.",
      reading: `The single most researched finding in learning science: rereading and highlighting *feel* effective and are not. Active retrieval — closing the book and forcing yourself to say what you just read — is 3–5× more effective per minute.\n\nMost students study for hours and remember little because they never leave the input phase.\n\nGanesha wrote the Mahabharata on the condition that Vyasa dictate without pause. But Ganesha only wrote lines *he had understood*. He was practicing retrieval, not transcription.`,
      practice: { name: "The Blank Page Test", durationMin: 20,
        instructions: `1. Study a topic for 10 minutes.\n2. Close everything. Blank page.\n3. Write everything you remember about it. Diagrams, definitions, examples.\n4. Only then open the book and see what you missed.\n5. The missing bits are what you actually need to restudy.` },
      reflection: "What subject have you 'studied' hours of and would flunk a blank-page test on?" },
    { day: 4, title: "Sleep Is A Study Technique",
      oneLine: "Memory consolidation happens during sleep. All-nighters delete what you learned.",
      reading: `Long-term memory formation depends on slow-wave sleep. When you skip sleep before an exam, you are not "trading rest for time" — you are literally uninstalling the material you spent the last day loading.\n\nAthletes know sleep is training. Students still treat it as optional. This is the biggest single leverage point in your grades that costs nothing.`,
      practice: { name: "The Same-Time Bedtime", durationMin: 5,
        instructions: `1. Pick a bedtime you can hit every night this week. Even 11 pm counts, if consistent.\n2. 30 minutes before: no screens, dim lights.\n3. Phone charging outside the bedroom.\n4. Note tomorrow how sharp your morning study block feels.` },
      reflection: "What would your grades look like if you slept 8 hours for a month?" },
    { day: 5, title: "The Cost of Comparison",
      oneLine: "Every hour spent worrying about what everyone else is scoring is an hour not spent studying.",
      reading: `Comparison is the emotional tax on ambitious students. Every scroll past a friend's achievement, every rank list check, every "am I falling behind" cycle burns real cognitive fuel. The fuel does not come back.\n\nThe students at the top of any class are not the ones comparing most. They are the ones who have quietly narrowed the field to themselves and their material.`,
      practice: { name: "The Narrowed Field", durationMin: 10,
        instructions: `1. Unfollow, mute, or hide 5 accounts that make you feel behind.\n2. Write on paper: "The only comparison that matters is me last month vs me now."\n3. Put it above your desk.\n4. When the comparison thought comes: read it.` },
      reflection: "Whose achievement have you been silently competing with in your own head?" },
    { day: 6, title: "The Exam-Day Breath",
      oneLine: "You have prepared for the exam. Now prepare the nervous system that will sit for it.",
      reading: `Exam anxiety is not weakness. It is your sympathetic nervous system correctly identifying threat and dumping cortisol. Cortisol shrinks working memory. That's why blanks happen.\n\nOne physiological tool reverses this in under a minute: the extended exhale. Longer exhale than inhale activates the vagus nerve and pulls you out of fight-or-flight.\n\nSeals use it. Surgeons use it. It is not optional woo.`,
      practice: { name: "4-8 Breath", durationMin: 5,
        instructions: `1. Inhale through nose, count of 4.\n2. Exhale through pursed lips, count of 8.\n3. Repeat 6 times.\n4. Do this now. Then do it before every study block this week. Then do it in the exam hall before you turn the paper over.` },
      reflection: "What is the exam story you tell yourself walking in? Rewrite it in one sentence." },
    { day: 7, title: "Meaning Under The Marks",
      oneLine: "The score matters. Not as much as you think. Almost never as much as your family thinks.",
      reading: `You will get a score. Life will continue. Ten years from now, the score will be a footnote and the person you became studying for it will be the story. The discipline, the honesty, the way you treated yourself under pressure — those compound. The score does not.\n\nGanesha's real gift is not scholarship. It is *vighnaharta* — remover of the obstacle. And the biggest obstacle for most students is not the syllabus. It is the belief that their worth is on a mark sheet.`,
      practice: { name: "The Worth Statement", durationMin: 10,
        instructions: `1. Write: "My worth is not on the mark sheet. It shows up in __." Fill three specific things (how I treat my mother, how I keep my word, how I study when no one's watching).\n2. Read it out loud.\n3. Keep it. Read it the night before your next exam.` },
      reflection: "If the mark did not exist, would you still study this? What does the answer tell you?" },
  ],
};

// ============================================================================
// 4. ATHLETES — THE MIND IN MOTION (Hanuman)
// ============================================================================
const ATHLETE_MIND: ShowroomProgram = {
  slug: "athlete-mind-in-motion",
  title: "The Mind In Motion",
  subtitle: "Seven days for athletes — pre-performance regulation, in-game focus, and the ethics of competition.",
  guru: "Hanuman",
  guruRole: "the greatest athlete in the epics — devotion, strength, and the humility that made both trustworthy",
  theme: "🏹",
  color: "from-orange-600/30 via-red-500/20 to-rose-600/10",
  category: "willpower",
  audience: "athletes",
  duration: "7 days",
  promise: "By day 7 you'll have a pre-game arousal protocol, an in-game reset for when it slips, and a clear frame for competition that doesn't turn winning into your whole identity.",
  days: [
    { day: 1, title: "Arousal Is A Curve",
      oneLine: "There is a physiological sweet spot for your event. Above it or below it, you lose.",
      reading: `The Yerkes-Dodson curve: performance rises with arousal to an optimum, then falls. Different sports have different peaks — a powerlifter wants near-maximum activation, a golfer near minimum. Same athlete, different peak per event.\n\nMost athletes never learn to *feel* their zone. They just show up and hope. The elite ones know their heart-rate window, their breath, their internal weather, and can move themselves into it deliberately.\n\nHanuman leaping the ocean is not raw hype. It is Jambavan reminding him who he is until the exact state is present. Then he jumps.`,
      practice: { name: "Name Your Zone", durationMin: 10,
        instructions: `1. Recall your best performance. Close eyes. What did the body feel like? Loose or tight? Fast heart or slow? Talkative or quiet mind?\n2. Recall your worst. Same questions.\n3. Write: "My zone feels like __."\n4. This week you're learning to steer into it, not hope for it.` },
      reflection: "How much of your performance variability is really preparation variability of arousal?" },
    { day: 2, title: "The Pre-Game Ritual",
      oneLine: "Rituals are not superstition. They are a nervous system's on-ramp to a specific state.",
      reading: `Every elite athlete has a pre-game ritual and defends it fiercely. Not because the socks are lucky, but because the *sequence* trains the body to enter game-state on cue. Skip it, arrive cold. Perform it, arrive ready.\n\nDesign matters. Rituals that hype further pull the over-aroused athlete out of zone. Rituals that settle pull the under-aroused athlete into it. Yours must match your event and your baseline.`,
      practice: { name: "Design Your Ramp", durationMin: 15,
        instructions: `1. Ask: do I usually arrive over-hyped or under-fired?\n2. If over: build a settling ramp (slow breath, headphones with calm music, one solo warm-up movement, one anchor phrase like "smooth is fast").\n3. If under: build an activating ramp (2 minutes of dynamic movement, up-tempo music, sharp verbal cue like "let's go").\n4. Sequence 3–5 steps, always in the same order. Run it at your next session.` },
      reflection: "Have you been using someone else's pre-game routine that never actually fits you?" },
    { day: 3, title: "The In-Game Reset",
      oneLine: "You will fall out of zone during the game. What defines elite is how fast you climb back.",
      reading: `Amateurs are broken by one mistake. Professionals reset in under 8 seconds and are already on the next play.\n\nThe reset is a rehearsed physical act: a specific breath, a specific word, a specific glance (some tennis players stare at their strings; some quarterbacks tap their helmet twice). The point is a repeatable interruption of rumination before it hijacks the next moment.`,
      practice: { name: "The 8-Second Reset", durationMin: 5,
        instructions: `1. Pick one physical anchor (touch your wristband, exhale hard once, tap your chest).\n2. Pair with one word: "next," "clear," "now."\n3. Rehearse: imagine a mistake in your sport, run the reset, imagine the next play.\n4. Repeat 10×.\n5. Use it in your next practice or game after every error.` },
      reflection: "Which mistake in your last game did you carry for how many plays?" },
    { day: 4, title: "Recovery Is Training",
      oneLine: "The adaptation happens between the sessions, not in them. Under-recover and you regress.",
      reading: `Muscle protein synthesis, tendon remodeling, nervous-system recovery — all happen in the 24–48 hours after load. Athletes who train hard and recover poorly are, physiologically, athletes who are getting worse in slow motion.\n\nHanuman is a strength archetype but his story emphasizes seva and stillness as much as leaping. The great ones alternate. The average ones grind.`,
      practice: { name: "The Recovery Audit", durationMin: 10,
        instructions: `1. Score last week 1–10 on: sleep hours, protein intake, stretching/mobility, one full rest day, screens off before bed.\n2. The two lowest scores are your recovery leaks.\n3. Fix one this week. Just one. Well.` },
      reflection: "Are you training hard, or are you avoiding rest because rest feels lazy?" },
    { day: 5, title: "Rival, Not Enemy",
      oneLine: "The people you compete against are the people who make you good. Treat them that way.",
      reading: `Toxic competition assumes the opponent's loss is your gain. Healthy competition — the sanatana kind — treats the opponent as the pressure without which you would never grow. You bow before, you fight all-out during, you shake hands after.\n\nHanuman fought fiercely and revered his opponents when they were worthy. The greatest wrestlers in every tradition speak the same way. The trash-talk is theater. Underneath, respect.`,
      practice: { name: "The Rival Letter", durationMin: 10,
        instructions: `1. Think of your current main rival (real or perceived).\n2. Write down three ways they have made you a better athlete.\n3. You don't need to send it. You need to internalize it.\n4. Next time you face them: play hard, then thank them (even silently).` },
      reflection: "Who has your competitive envy quietly turned into an enemy who was actually a teacher?" },
    { day: 6, title: "The Body That Ages",
      oneLine: "Every athlete gets old. The ones who thrive after have a relationship with the sport, not just a body inside it.",
      reading: `An athlete's biggest silent crisis is not the injury. It is the day the body will not do what it used to. Athletes who tied identity to peak output collapse when peak fades. Athletes who tied identity to the *practice* — the discipline, the teaching, the presence — keep going for life.\n\nBuild the second identity now, at peak, and old age becomes a promotion.`,
      practice: { name: "The Beyond-Peak Vision", durationMin: 15,
        instructions: `1. Imagine yourself 20 years past peak. Still connected to this sport somehow.\n2. Who are you in it? Coach? Elder? Referee? Parent-teacher?\n3. Write one paragraph about that person.\n4. Ask: does anything in that person need me to start seeding today?` },
      reflection: "What will you be to this sport when you cannot do it anymore?" },
    { day: 7, title: "The Deeper Game",
      oneLine: "The trophy is a symbol for something. Get clear on what — or the symbol becomes the whole thing.",
      reading: `Every athlete is chasing something under the medal: their father's approval, their own proof, the feeling of aliveness, a way out of their town. Nothing wrong with any of them — until the medal arrives and the underneath is still unfilled.\n\nHanuman's greatness is not that he was the strongest. It is that his strength was always in service of something larger. Ram-seva. Devotion. Bigger than the outcome.\n\nName your bigger than. Play toward it.`,
      practice: { name: "The Bigger Than", durationMin: 15,
        instructions: `1. Write: "Under the trophy, I am really playing for __."\n2. Then: "The version of me that plays for that is __."\n3. Then: "This week I will act like that version by __."\n4. One small action. Do it before Sunday.` },
      reflection: "If you won everything tomorrow, what would still be unmet? That's the real game." },
  ],
};

// ============================================================================
// 5. FOUNDERS — THE FOUNDER'S CHAIR (Chanakya)
// ============================================================================
const FOUNDER_CHAIR: ShowroomProgram = {
  slug: "founder-decision-loneliness",
  title: "The Founder's Chair",
  subtitle: "Seven days for founders — the loneliness of the top seat, the ethics of scale, and the private practice that keeps you sane.",
  guru: "Chanakya",
  guruRole: "the strategist who built an empire and wrote its operating manual — brilliant, ruthless, and unflinchingly clear-eyed",
  theme: "♟️",
  color: "from-slate-600/30 via-zinc-500/20 to-stone-500/10",
  category: "decision",
  audience: "founders",
  duration: "7 days",
  promise: "By day 7 you'll have a weekly solo review, a clear list of what only you can do vs what you're clinging to, and one honest peer relationship where you don't have to be the founder.",
  days: [
    { day: 1, title: "The Loneliness Is Structural",
      oneLine: "You're not lonely because you're bad at friendship. You're lonely because the chair is designed that way.",
      reading: `Founders sit at an information asymmetry no one else on the cap table has. You know the runway, the co-founder tensions, the customer risk, the personal cost. You cannot fully share these with the team (bad for morale), your investors (bad for trust), your spouse (unfair load), or your parents (they'll panic).\n\nMost founders interpret this as personal failure — "I don't have real friends" — when it is actually role architecture.\n\nChanakya lived it. The Arthashastra reads like it was written by someone who understood that the person at the top has to build specific containers or go quietly mad.`,
      practice: { name: "The Container Map", durationMin: 10,
        instructions: `1. List the 5 hardest things weighing on you.\n2. For each, ask: who is the *right* container for this? (fellow founder / therapist / spouse / board / no one — my journal).\n3. Notice how many you've been dumping in the wrong container, or none at all.` },
      reflection: "Which weight have you been carrying alone because it 'doesn't fit' anywhere?" },
    { day: 2, title: "The Weekly Solo",
      oneLine: "Founders who don't self-review are debugged by the market. It's slower and more expensive.",
      reading: `The best founders block 90 minutes weekly, alone, no laptop, to review their own head. Not the metrics — the head. Am I avoiding a hard conversation? Am I drifting from the original why? Have I lied by omission to anyone this week?\n\nThis is not therapy and it is not journaling. It is corporate hygiene at the highest level of the org: the CEO's own operating system.`,
      practice: { name: "The Sunday Review", durationMin: 45,
        instructions: `1. Sunday morning, coffee, notebook. No screens.\n2. Answer: (a) What did I avoid this week? (b) Whose truth did I flinch from? (c) What am I telling myself is fine that isn't? (d) What is the one thing next week that only I can do?\n3. Write one action for each.` },
      reflection: "When did you last review your own leadership without someone else in the room?" },
    { day: 3, title: "Delegate Or Suffocate",
      oneLine: "You are the bottleneck. You built it that way. Now you can't scale through it.",
      reading: `Every founder's second year has the same crisis: the thing that made you succeed in year one — obsessive control — is now killing year two. The team is capable and disempowered. Decisions queue at your desk. You are working 90 hours and it is *slowing* the company.\n\nThe fix is not "delegate more." The fix is to write down which decisions must stay with you and which cannot. Once written, everything else is genuinely off your plate.`,
      practice: { name: "The Decision Ledger", durationMin: 20,
        instructions: `1. Two columns: "Only I decide" and "Someone else decides, I trust their call."\n2. Force yourself to put at least 15 items in the second column.\n3. Tell the person who now owns each one, today.\n4. Do not check back for a week.` },
      reflection: "Which decision have you kept because it makes you feel needed, not because it needs you?" },
    { day: 4, title: "The Ethics of Scale",
      oneLine: "The choices you make at 10 people become the culture at 1,000. What you tolerate, you install.",
      reading: `Founders think culture is set later, by hires and offsites. It is not. It is set by the earliest tolerated behavior. The first time a top performer was cruel and stayed. The first time a lie made a quarter and no one named it. Those moments become the memory of the company.\n\nChanakya was ruthless in strategy and rigorous in ethics inside his own court. He knew the second was the load-bearing wall for the first.`,
      practice: { name: "The Tolerated List", durationMin: 15,
        instructions: `1. Write down 3 behaviors currently happening in your company that you'd be embarrassed for a new hire to see on day one.\n2. For each: who is doing it, why has it been tolerated, what does tolerating it teach the org.\n3. Pick one to address this week.` },
      reflection: "What have you tolerated because addressing it feels expensive right now?" },
    { day: 5, title: "The Body of the Founder",
      oneLine: "The company cannot outperform the physiology of the person running it.",
      reading: `Founders romanticize the grind. Investors love the grind narrative because it externalizes cost onto the founder. The founder pays the bill in sleep debt, back pain, ruined relationships, and eventually — statistically — a health crisis at 45.\n\nThere is no company worth this. And ironically, the founders who ran the marathon, not the sprint, built the biggest companies.`,
      practice: { name: "The Non-Negotiable Three", durationMin: 10,
        instructions: `1. Choose three physical anchors you will hold *no matter what happens at work this year*: (e.g. 7 hours sleep, one walk daily, one full day off).\n2. Write them.\n3. Tell one person. Ask them to call you out if you break them.\n4. Reschedule the calendar around them, starting this week.` },
      reflection: "Which health metric have you traded for how much revenue this year?" },
    { day: 6, title: "One Real Peer",
      oneLine: "Not a mentor. Not an investor. One other founder who can see you naked and won't leave.",
      reading: `The single largest predictor of founder mental health is the presence of one authentic peer relationship with another founder at a similar stage. Not a group, not a mastermind — one person you text at 11 pm when you're spiralling and they know exactly what you mean.\n\nThis is not built by attending events. It's built by choosing one person, being embarrassingly honest first, and showing up for them consistently.`,
      practice: { name: "The Reach", durationMin: 15,
        instructions: `1. Name one founder you respect and could tolerate being honest with.\n2. Send a message today: "I'm doing a weekly check-in with one other founder to stay sane. Want to try it — 30 min every Friday for a month, then decide?"\n3. Do not overthink the message. Send it.` },
      reflection: "Who is the founder you'd trust with the story you don't tell your board?" },
    { day: 7, title: "The Company You'd Be Proud Of At 60",
      oneLine: "The exit is a moment. The decade of who you were building it is the life.",
      reading: `Someday you'll exit, or die, or hand it off. The company will continue or not. What will remain is who you became in the seat. Whether you were honest. Whether the people around you grew. Whether you stayed in your marriage. Whether your kids know you.\n\nChanakya's genius was placing every tactical decision inside a longer arc. He built for what would outlive him. Founders who never lift their eyes to that arc arrive at the exit rich, exhausted, and confused about what they did with the years.`,
      practice: { name: "The 60-Year-Old Letter", durationMin: 20,
        instructions: `1. Write a letter from your 60-year-old self to today's you.\n2. Answer: what are they grateful you did? What are they grieving that you didn't?\n3. Pick one thing from that letter and act on it this week — not next quarter.` },
      reflection: "What would the 60-year-old you tell you to stop doing right now?" },
  ],
};

