// 7. TEACHERS — THE PRESENT TEACHER (Saraswati)
// ============================================================================
const TEACHER_PRESENT: ShowroomProgram = {
  slug: "teacher-classroom-presence",
  title: "The Present Teacher",
  subtitle: "Seven days for classroom teachers — holding a room of children without losing yourself in it.",
  guru: "Saraswati",
  guruRole: "the goddess of learning — patron of every human who has tried to open another human's mind",
  theme: "🪷",
  color: "from-pink-500/30 via-rose-500/20 to-red-400/10",
  category: "attention",
  audience: "teachers",
  duration: "7 days",
  promise: "By day 7 you'll have a pre-class centering, a de-escalation move that works on real classrooms, and one honest boundary with parent expectations.",
  days: [
    { day: 1, title: "The Room Reads Your Nervous System",
      oneLine: "Thirty small nervous systems mirror one large one. You are the largest one in the room.",
      reading: `Children's autonomic systems co-regulate with the adult they trust. If you enter class tight, they tighten. Enter scattered, they scatter. Enter grounded, most (not all) settle into your ground.\n\nThis is not "kids can smell fear." It is *polyvagal co-regulation* — a measurable transfer of state from calm bodies to activated ones through voice tone, face, and pace.\n\nWhich means: the most important classroom management tool is your own physiology, arriving at the door.`,
      practice: { name: "The Threshold Pause", durationMin: 3,
        instructions: `1. Before you open the classroom door: stop.\n2. Three slow exhales.\n3. Drop shoulders.\n4. One sentence: "I am the calm."\n5. Then enter.\n6. Do this before every class this week.` },
      reflection: "How much of last week's chaos entered the room with you?" },
    { day: 2, title: "Attention Is Given, Not Demanded",
      oneLine: "Loud teachers get compliance. Present teachers get attention. Different things.",
      reading: `The loudest classroom management strategies (raise voice, use points, threaten) produce short-term compliance and long-term erosion. Children learn to give the surface behavior and check out inside.\n\nGenuine attention is offered when the teacher is genuinely worth listening to — which is a function of presence, clarity, and care, not decibels.\n\nSaraswati's power is that people *want* to listen. Not that she demands it.`,
      practice: { name: "The Quiet Signal", durationMin: 5,
        instructions: `1. Choose one non-verbal attention signal (a bell, a specific hand gesture, standing in one spot).\n2. Teach the class this week: this signal means eyes and quiet, within 5 seconds.\n3. Never raise your voice with it — just wait.\n4. Track how the wait time shrinks across the week.` },
      reflection: "Which of your management moves shrink your students, and which grow them?" },
    { day: 3, title: "The Child Who Triggers You",
      oneLine: "There is one. The reaction is yours to understand, not theirs to fix.",
      reading: `Every teacher has a student who lights something up. The defiance, the neediness, the loudness reminds you of something — a sibling, a version of yourself, a parent. The reaction is disproportionate and you know it.\n\nUntil you name what that student *represents* in your own history, you will keep punishing them for it and hating yourself after.`,
      practice: { name: "The Trigger Journal", durationMin: 15,
        instructions: `1. Name the student.\n2. Write: "When they do X, I feel Y. This reminds me of __."\n3. Sit with the memory that surfaces.\n4. Tomorrow, look at that student with the awareness: "You are not that person from my history."\n5. Notice the small shift in your own tone.` },
      reflection: "Which student are you fighting a shadow through?" },
    { day: 4, title: "The Parent At The Gate",
      oneLine: "Parent expectations expand until met with a clear, warm boundary.",
      reading: `The modern teacher fields evening emails, weekend WhatsApps, and parent anxieties as if the classroom never closes. This is unsustainable and the profession is quietly leaving because of it.\n\nBoundaries with parents are not coldness. They are the container that makes your Monday morning possible. Warm boundaries hold better than resentful availability.`,
      practice: { name: "The Communication Window", durationMin: 15,
        instructions: `1. Decide your window: which hours, which channel, what response time.\n2. Send one polite email to all parents this week: "For everyone's benefit, I respond to messages Mon-Fri, 4-5 pm. Emergencies via the school office."\n3. Then hold it. Do not answer the 9 pm message tonight.` },
      reflection: "What availability have you offered because you were afraid to say no?" },
    { day: 5, title: "Every Class Has A Rhythm",
      oneLine: "Attention comes in waves. Ride the wave, don't fight it.",
      reading: `Children's sustained attention is roughly their age in minutes. A class of 10-year-olds cannot focus for 45 straight minutes on one modality. The wave breaks around minute 12–15, then again around 25.\n\nMasterful teachers don't push through the drop. They *plan* for it — a shift in modality (from listening to writing, from sitting to moving) exactly when the wave breaks. The class stays with them because the class was designed for their nervous system, not against it.`,
      practice: { name: "Design One Wave", durationMin: 20,
        instructions: `1. Take your next lesson plan.\n2. Mark the 12-minute point and the 25-minute point.\n3. At each, insert a 60-second modality shift (stand and stretch / partner talk / silent write / breath).\n4. Run it. Note the difference in the last 15 minutes of class.` },
      reflection: "How much of your class energy have you spent dragging kids past their natural wave?" },
    { day: 6, title: "The One Sentence That Sticks",
      oneLine: "Ten years from now, one student will remember one thing you said. Say it on purpose.",
      reading: `Adults universally remember one or two lines from a teacher decades later. Rarely a lesson. Usually a moment of being *seen* — a specific sentence spoken directly, warmly, with belief.\n\nThe currency of teaching is these moments. You cannot manufacture them, but you can be alert for the opening and step into it when it comes.`,
      practice: { name: "The Named Seeing", durationMin: 10,
        instructions: `1. This week, catch one student in a moment of quiet effort no one else noticed.\n2. Say to them, one-on-one, briefly, specifically: "I noticed you did X. That takes __. I saw it."\n3. Move on. Don't oversell.\n4. Do this once a day, different student each time.` },
      reflection: "Whose sentence do you still carry from your own education?" },
    { day: 7, title: "Why You Teach",
      oneLine: "Under the tiredness is a reason you chose this. Guard it.",
      reading: `Teaching is one of the last professions where the reason for doing it is not compensation. This is both its glory and its exploitation risk. The system counts on your love and pays around it.\n\nProtect the love. Not by working more, but by remembering weekly why you started. Without that, the love slowly gets extracted and you become an administrator of children.\n\nSaraswati is worshipped once a year in India on a specific day — students touch her feet, teachers are honored. The ritual exists because without it, the reason gets forgotten.`,
      practice: { name: "The Small Vow", durationMin: 15,
        instructions: `1. Write one line: "I teach because __."\n2. Under it: "This year I will protect that by __." (one specific act — refusing one committee, keeping Sunday sacred, whatever).\n3. Read weekly.` },
      reflection: "What would you have to stop doing to be the teacher you originally wanted to be?" },
  ],
};

// ============================================================================
// 8. GRIEF — THE ROOM CALLED GRIEF (Shiva)
// ============================================================================
const GRIEF_ROOM: ShowroomProgram = {
  slug: "grief-and-loss",
  title: "The Room Called Grief",
  subtitle: "Seven days for those in fresh loss — a companion, not a cure.",
  guru: "Shiva",
  guruRole: "the one who sat with Sati's body and did not pretend it hadn't happened — the archetype of grief that does not skip",
  theme: "🌒",
  color: "from-indigo-700/30 via-violet-700/20 to-purple-800/10",
  category: "shadow",
  audience: "grief",
  duration: "7 days",
  promise: "By day 7 you'll have permission to grieve on your own timeline, one daily ritual of remembrance, and a working understanding that healing is not forgetting.",
  days: [
    { day: 1, title: "The Timeline Is Not Real",
      oneLine: "There is no schedule for grief. Anyone who gives you one is uncomfortable, not right.",
      reading: `Modern culture allows grief for a few weeks. Then the world expects you back. Colleagues stop asking. Friends assume you're "doing better." The pressure to perform recovery becomes its own grief, layered on the first.\n\nOlder cultures knew: grief is a season, sometimes a year, sometimes longer. It does not respond to being rushed. Rushing it drives it underground where it becomes something worse.\n\nShiva sat with Sati's body for a long time. The gods thought he was mad. He was doing something older than madness — he was refusing to skip.`,
      practice: { name: "The Permission Slip", durationMin: 10,
        instructions: `1. Write on paper: "I give myself permission to grieve for as long as this takes. I will not perform recovery for anyone's comfort."\n2. Sign it and date it.\n3. Keep it visible.\n4. Read when anyone (including yourself) tries to hurry you.` },
      reflection: "Whose timeline have you been trying to grieve on?" },
    { day: 2, title: "The Waves Are Not Progress",
      oneLine: "You will not be sadder each day, less sad each week. Grief comes in waves for reasons no one can predict.",
      reading: `The 'stages of grief' were originally a model for terminal patients, not for the bereaved. The bereaved do not proceed linearly through denial-anger-bargaining. They surf waves — one good week, then a song plays and it's day one again.\n\nWhen you know this, the wave is bearable. When you think you should be "past it," the same wave feels like proof you're broken.`,
      practice: { name: "Naming The Wave", durationMin: 5,
        instructions: `1. When a wave hits today: pause.\n2. Say (out loud if alone, silently if not): "This is a wave. It is not a step back."\n3. Let it be there. Don't try to solve it.\n4. It will pass in its own time.` },
      reflection: "What triggered your last unexpected wave?" },
    { day: 3, title: "The Body Grieves Too",
      oneLine: "Grief is not only a feeling. It is a full-body event. Fatigue, appetite, sleep — all shift.",
      reading: `Cortisol rises. Sleep fractures. Appetite disappears or explodes. The immune system dips. Cardiac events rise measurably in the year after loss. This is not weakness. This is what the body does when a bond breaks.\n\nGrief without physical care becomes physical illness. The care doesn't cure — it holds you through.`,
      practice: { name: "The Minimum", durationMin: 10,
        instructions: `1. Commit today only to three things: one meal, one glass of water each hour you're awake, one short walk outside (even 5 minutes).\n2. Nothing else is required.\n3. If any get done, that is enough for today.` },
      reflection: "Which of your basics has slipped since the loss?" },
    { day: 4, title: "The Rituals That Hold You",
      oneLine: "Every culture invented grief rituals because grief without ritual is grief without a container.",
      reading: `Sitting shiva, wearing white, lighting a lamp on the anniversary, keeping a photograph — these are not superstition. They are the container that lets grief be *held* by something outside your own overwhelmed mind.\n\nWithout ritual, grief becomes formless and endless. With ritual, it has a shape you can move within.`,
      practice: { name: "One Small Ritual", durationMin: 15,
        instructions: `1. Choose one small daily act of remembrance:\n   - Light a candle at the same time each evening.\n   - Speak their name aloud once a day.\n   - Keep one photograph in a specific spot and pause at it daily.\n2. Do it today. Do it tomorrow. Do it for the next 40 days.` },
      reflection: "What ritual, if any, has your culture given you for this? What would you invent?" },
    { day: 5, title: "Say Their Name",
      oneLine: "People stop saying their name because they are afraid it will hurt you. It hurts more that they've stopped.",
      reading: `The most common thing the bereaved report is loneliness *in the name*. Everyone tiptoes. No one mentions them. It's as if they're being erased twice — first by death, then by discomfort.\n\nYou can give people permission. Most will exhale with relief.`,
      practice: { name: "The Permission To Others", durationMin: 10,
        instructions: `1. Tell one person close to you: "Please say their name. Please tell me stories about them. Silence hurts more than tears."\n2. Then, this week, say their name yourself in a normal conversation. Not as a heavy moment. Just as: "X used to love this."` },
      reflection: "Who around you needs your permission to bring them up?" },
    { day: 6, title: "The Guilt That Comes Uninvited",
      oneLine: "The 'if only' loops are a normal feature of grief. They are not evidence of your guilt.",
      reading: `Almost every grieving person cycles through: "if I had called sooner," "if I had insisted on the second opinion," "if I had said I loved them." These loops are the mind trying to feel in control of something that was not controllable.\n\nThey are not confession. They are the shape of love with nowhere to go.`,
      practice: { name: "The If Only Release", durationMin: 15,
        instructions: `1. Write down every "if only" you're carrying about the loss.\n2. Under the list, write: "These are my love with nowhere to go. They are not evidence of my failure."\n3. Keep the list. Read the sentence when the loops start again.` },
      reflection: "Which 'if only' has been running most in you?" },
    { day: 7, title: "They Are Not Gone If You Carry Them",
      oneLine: "Grief does not end. It changes shape. What was outside you becomes part of who you are.",
      reading: `You will not "get over" this. You will get *around* it. The loss becomes a feature of your interior landscape. In some ways, they become more present, not less — you carry their humor, their expressions, their advice, into rooms they never entered.\n\nThis is not consolation for the physical loss. It is the truth that runs alongside it. The bond is not broken. It has been re-formed.\n\nShiva did not stop loving Sati. He became different because of her.`,
      practice: { name: "The Carrying", durationMin: 20,
        instructions: `1. Write: "I carry them forward when I __." Fill three specifics (the way I laugh / how I treat waiters / my willingness to say the hard thing).\n2. Choose one to lean into this month, in their honor.\n3. Read the list on their birthday, their anniversary, whenever the wave returns.` },
      reflection: "What of them is now, quietly, part of you?" },
  ],
};

