// 9. CORPORATE — THE TEAM THAT WENT COLD (Krishna)
// ============================================================================
const TEAM_REPAIR: ShowroomProgram = {
  slug: "corporate-team-repair",
  title: "The Team That Went Cold",
  subtitle: "Seven days for managers of teams that have quietly stopped trusting each other.",
  guru: "Krishna",
  guruRole: "the field-marshal who ran a coalition of warring egos and made them fight together",
  theme: "🤝",
  color: "from-blue-500/30 via-indigo-500/20 to-violet-500/10",
  category: "purpose",
  audience: "corporate",
  duration: "7 days",
  promise: "By day 7 you'll have named the specific breach, run one repair conversation, and installed one weekly ritual that keeps trust warm.",
  days: [
    { day: 1, title: "The Cold Is A Symptom",
      oneLine: "Teams don't drift into distance. Something specific happened. Find it.",
      reading: `Managers describe cold teams as if the temperature dropped by weather. It didn't. There was a moment: a broken promise, a taken credit, a fired peer no one processed, a reorg no one explained. From that moment forward the team was different, and nobody named it.\n\nRepair is impossible until the moment is named. Team-building offsites without naming the moment feel forced and change nothing.`,
      practice: { name: "The Moment Audit", durationMin: 20,
        instructions: `1. Ask each of your directs, 1:1, quietly: "When did the team feel warmer than it does now? What happened between then and now?"\n2. Listen. Don't defend. Don't fix.\n3. Look for the moment that shows up in 3+ answers. That's the breach.` },
      reflection: "What has the team been polite about that they are not okay with?" },
    { day: 2, title: "The Manager Was In It",
      oneLine: "You are almost certainly part of the breach. Not the villain, but part.",
      reading: `Managers investigating team dysfunction usually locate the problem in "the team." Rarely in themselves. Almost every cold team has a manager move — a favoritism, a bypass, a broken word — that seeded the cold.\n\nAcknowledging this is not weakness. It is the single most trust-recovering thing a manager can do.`,
      practice: { name: "The Own-Your-Part List", durationMin: 15,
        instructions: `1. Write down: what have I done or failed to do that contributed to this cold?\n2. Force yourself to find at least three items.\n3. This is not for sending. It is for you to hold before you enter any repair conversation.` },
      reflection: "Which favorite have you been unaware you were favoring?" },
    { day: 3, title: "The Naming Conversation",
      oneLine: "One team meeting where the elephant is named directly. Not fixed. Named.",
      reading: `The single highest-leverage move in team repair is one meeting where the leader says out loud: "Something has shifted in this team. Here's what I've seen. Here's my part in it. I want to hear yours." No slides. No fixes. Just naming.\n\nMost of the healing happens in the naming itself. The fix comes later.`,
      practice: { name: "The Naming Meeting", durationMin: 60,
        instructions: `1. Schedule 60 minutes with the team this week. No agenda slides.\n2. Open with your own honest naming: what you've seen, what you're contributing, why you called this meeting.\n3. Then ask each person to name one thing they've been holding.\n4. Do not defend. Do not solve. Take notes.\n5. Close with: "Thank you. I'll come back with what I'm going to do about my part by Friday."` },
      reflection: "What are you afraid will happen if you name it? What's already happening because you don't?" },
    { day: 4, title: "Small Repairs, Named Out Loud",
      oneLine: "Big culture change is a myth. Small named repairs are the actual mechanism.",
      reading: `Trust is rebuilt in specific, small, visible acts — not in "we're going to be more collaborative going forward." Announce the small acts. "I promised X and didn't do it — here's what I'm changing." Model what you want the team to do.`,
      practice: { name: "The Public Repair", durationMin: 15,
        instructions: `1. Choose one specific thing you named yesterday.\n2. Take one visible action this week to repair it.\n3. Announce it in the next team meeting, briefly: "You'll notice I'm now doing X. That's because of Y. I'll keep doing it."\n4. Then keep doing it.` },
      reflection: "Which broken promise of yours has the team quietly memorized?" },
    { day: 5, title: "Kill The Backchannels",
      oneLine: "Every cold team runs on backchannels. Every warm team routes truth through the room.",
      reading: `In cold teams, the real conversation happens in DMs, coffees, and side-emails after the meeting. The meeting itself becomes theater. This is the tell-tale sign.\n\nWarming a team means making the room safe enough for the backchannel to move into it. Which requires the manager to receive hard truth in the room without punishment.`,
      practice: { name: "The Received Truth", durationMin: 10,
        instructions: `1. In your next team meeting, invite one hard question live.\n2. When it comes, thank the person specifically: "Thank you for saying that here. That's exactly what I need to hear in this room."\n3. Do not punish the person later, even subtly. Watch yourself.\n4. Do this again. And again.` },
      reflection: "Which of your team members has stopped telling you the truth?" },
    { day: 6, title: "The Weekly Ritual",
      oneLine: "Trust is not a state. It's a habit built by a small weekly act.",
      reading: `The teams with the highest sustained trust have one small weekly ritual — a Monday round where everyone shares one work thing and one life thing, a Friday where the manager thanks two specific people publicly. Something small, repeated, protected.\n\nThe ritual is boring. That's why it works. It survives the weeks when everything else is on fire.`,
      practice: { name: "Install The Ritual", durationMin: 15,
        instructions: `1. Choose one small weekly ritual (5–10 minutes, not a whole meeting).\n2. Announce it. Start it this week.\n3. Do not skip it, even when calendars are burning. Especially then.\n4. Reassess after 8 weeks.` },
      reflection: "What ritual would you have wanted from a manager earlier in your career?" },
    { day: 7, title: "Krishna's Coalition",
      oneLine: "The Pandava army was a coalition of enormous egos. Krishna's genius was not making them agree — it was making them fight together anyway.",
      reading: `Great teams are not made of people who agree. They are made of people who trust the manager enough to bring their disagreement into the room, be heard, then align on the plan and execute together.\n\nKrishna did not flatten Arjuna, Bhima, or Yudhishthira into one voice. He held the tension of their differences and directed it at the real enemy. That is what your team needs from you.`,
      practice: { name: "The Coalition Note", durationMin: 15,
        instructions: `1. Write down each direct report's core strength and core edge.\n2. For each, one sentence: "I direct their strength by __." "I hold their edge by __."\n3. Keep this. Update quarterly.\n4. Manage from this note, not from your feelings about them.` },
      reflection: "Which of your team members have you been trying to change instead of direct?" },
  ],
};

