// 11. HEALERS — THE THERAPIST'S OWN ROOM (The Witness)
// ============================================================================
const THERAPIST_ROOM: ShowroomProgram = {
  slug: "healers-therapist-hygiene",
  title: "The Therapist's Own Room",
  subtitle: "Seven days for therapists and coaches — clean transference, real boundaries, and a private practice for the practitioner.",
  guru: "The Witness",
  guruRole: "the awareness that watches without becoming — the only capacity in the practitioner that can hold client material cleanly",
  theme: "🪞",
  color: "from-fuchsia-500/30 via-purple-500/20 to-violet-600/10",
  category: "self-inquiry",
  audience: "healers",
  duration: "7 days",
  promise: "By day 7 you'll have a between-session cleansing, a transference audit, and one honest supervision or peer relationship where you get to be the client.",
  days: [
    { day: 1, title: "You Cannot Take Clients Deeper Than You've Gone",
      oneLine: "Your ceiling is your client's ceiling. This is not a metaphor.",
      reading: `A therapist can only sit with what they can sit with in themselves. When a client brings material the therapist has not integrated, the therapist unconsciously deflects — a joke, a reframe, a redirect. The client learns "we don't go there" and stops.\n\nThis is why every serious therapeutic tradition requires the practitioner to have their own ongoing work. Not because they are broken. Because their range *is* the container.`,
      practice: { name: "The Ceiling Check", durationMin: 15,
        instructions: `1. List three themes your clients repeatedly avoid.\n2. Ask: which of these do I also avoid?\n3. Do not fix today. Just notice: the overlap is the map of your own next work.` },
      reflection: "Which theme have your clients stopped bringing? What did you communicate to make them stop?" },
    { day: 2, title: "Between-Session Hygiene",
      oneLine: "Client residue is a real thing. Rinse between sessions or you carry every one into the next.",
      reading: `Empathic therapists absorb autonomic states from clients — heart rate, breath, tension patterns. Without a between-session reset, session 3 is receiving what session 1 left behind, and the practitioner is receiving it all by session 6.\n\nThe reset is small and non-negotiable: 90 seconds, always the same, between every client.`,
      practice: { name: "The 90-Second Rinse", durationMin: 2,
        instructions: `1. Between each client today: stand up. Physically.\n2. Wash hands with intention.\n3. 3 slow exhales, longer than inhales.\n4. Silent phrase: "That session is complete. I return to me. The next person deserves a fresh room."\n5. Then the next client.` },
      reflection: "How often do you take the last client's state into your evening?" },
    { day: 3, title: "Transference As Data",
      oneLine: "Every strong feeling about a client is information about them, about you, or about the field between you. Sort it.",
      reading: `The therapist who feels unusually protective, irritated, aroused, or bored with a client is receiving valuable data — but only if they process it. Unprocessed, it leaks into technique. Processed, it becomes a diagnostic instrument.\n\nSupervision exists for this. Peer consultation exists for this. Journaling can bridge when the others are absent.`,
      practice: { name: "The Transference Note", durationMin: 15,
        instructions: `1. Pick one client who evokes a strong feeling in you.\n2. Write: "When I'm with X, I feel Y. This might be about (them / me / the dynamic between us)."\n3. If mostly about you: put it in your own therapy this month.\n4. If mostly about them: bring to supervision.\n5. If about the dynamic: consider naming it gently in the next session.` },
      reflection: "Which client have you been treating from a countertransference you haven't named?" },
    { day: 4, title: "The Boundary Is Kindness",
      oneLine: "Clients who text you at midnight are not being helped by your reply. They are being trained.",
      reading: `Therapists who blur time boundaries out of care are inadvertently teaching clients that their emotional regulation lives on the therapist's phone. This delays the client's development of internal capacity and burns the therapist out.\n\nBoundaries are not coldness. They are the container that makes the work possible. Delivered warmly, they become part of the treatment.`,
      practice: { name: "The Warm Boundary Script", durationMin: 15,
        instructions: `1. Write your standard reply for off-hours contact: "I got your message. I don't do therapy over text — the work needs the frame of session. If this is an emergency, please call [crisis line]. Otherwise, let's hold it and bring it to Tuesday."\n2. Use it every time. Do not vary based on how urgent the message feels.\n3. Notice how many clients grow into their own regulation.` },
      reflection: "Which client is on your phone in a way you'd advise a colleague to end?" },
    { day: 5, title: "The Practitioner's Practice",
      oneLine: "You are not exempt from what you prescribe. You need meditation, movement, and connection more than most.",
      reading: `Therapists prescribe practices they don't do. They tell clients about journaling, breath work, walks, therapy — and skip them themselves. The result is a practitioner who is a curator of tools they don't use, and the clients feel the disconnection even if they can't name it.\n\nDo the practice you prescribe. Or stop prescribing it.`,
      practice: { name: "The Prescribed To Self", durationMin: 20,
        instructions: `1. List 3 practices you regularly recommend to clients.\n2. Circle the ones you do not currently do.\n3. Pick one. Do it every day this week — as your client would be asked to.\n4. Notice what you now know about it that you didn't before.` },
      reflection: "Which of your recommendations have you not lived in years?" },
    { day: 6, title: "The Therapist's Own Therapist",
      oneLine: "The single non-negotiable of long-term practice. Not once. Forever.",
      reading: `Every mature tradition — psychodynamic, contemplative, medical — requires ongoing personal work of its practitioners. Not because they are ill. Because sitting with human suffering weekly changes the practitioner, and that change needs a container.\n\nThe therapist without a therapist is a practitioner slowly filling with unmetabolized material. The end state is not neutral — it is cynical, brittle, or extractive.`,
      practice: { name: "The Recommitment", durationMin: 15,
        instructions: `1. If you have a therapist / supervisor / peer group: this week, bring the *hardest* thing you've been carrying, not the safe one.\n2. If you don't: today, contact two candidates and schedule intake calls.\n3. This is not optional infrastructure. It is the load-bearing wall of the practice.` },
      reflection: "Whose therapist are you? Who is yours?" },
    { day: 7, title: "The Witness Underneath",
      oneLine: "Under all technique is one capacity — the ability to be present without becoming. Cultivate that above all.",
      reading: `Modalities come and go. What actually heals is a specific quality of presence in the practitioner: warm, undefended, and *not fused* with the client's material. The client feels held and free at the same time.\n\nThis capacity is not a technique. It is a state — the witness state — that grows through your own contemplative practice. The best therapists across schools all have some version of it. Without it, technique is scaffolding around an empty room.`,
      practice: { name: "The Witness Sit", durationMin: 15,
        instructions: `1. Sit for 15 minutes today, eyes closed.\n2. Notice thoughts, feelings, sensations. Do not follow.\n3. Ask silently: "Who is watching all of this?"\n4. Rest in the watcher.\n5. This is the state to bring into every session for the rest of your career.` },
      reflection: "When you are at your best with a client, what quality is present in you? How do you cultivate it outside sessions?" },
  ],
};

